// Web runtime build of cinematic-motlab/scenes/cinematic.js (generated by tools/build_web.py).
// Changes: image filters are baked once per image (no per-frame ctx.filter, works on Safari),
// canvas subtitles are disabled (HTML captions), mountScene is replaced by the player.
// Shared cinematic rendering engine for TERRA NOVA — Opening Cinematic (1920x1080, 24 fps)
export const W = 1920;
export const H = 1080;
export const TAU = Math.PI * 2;

export const clamp = (v, lo = 0, hi = 1) => Math.min(hi, Math.max(lo, v));
export const lerp = (a, b, k) => a + (b - a) * k;
export const span = (t, a, b) => clamp((t - a) / Math.max(1e-5, b - a));
export const easeOutCubic = k => 1 - (1 - clamp(k)) ** 3;
export const easeOutExpo = k => (k = clamp(k), k >= 1 ? 1 : 1 - Math.pow(2, -10 * k));
export const easeInOutSine = k => 0.5 - 0.5 * Math.cos(Math.PI * clamp(k));

export function loadImage(src) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error('Failed to load image: ' + src));
    img.src = src;
  });
}

// Deterministic pseudo-random for particles
function hash(n) {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453123;
  return s - Math.floor(s);
}


// ---- one-time filter baking (replaces per-frame ctx.filter) ----
const _baked = new Map();
function parseFilter(str) {
  const f = { blur: 0, brightness: 1, saturate: 1, contrast: 1 };
  for (const m of str.matchAll(/(blur|brightness|saturate|contrast)\(([\d.]+)(px)?\)/g)) f[m[1]] = parseFloat(m[2]);
  return f;
}
export function bakedImage(img, filter) {
  if (!filter) return img;
  let byImg = _baked.get(img);
  if (!byImg) { byImg = new Map(); _baked.set(img, byImg); }
  if (byImg.has(filter)) return byImg.get(filter);
  const f = parseFilter(filter);
  const iw = img.naturalWidth || img.width, ih = img.naturalHeight || img.height;
  // blur is emulated by drawing small and letting the GPU upscale smoothly (two-step downsample)
  const k = f.blur > 0 ? Math.max(0.035, Math.min(1, 2.2 / f.blur)) : 1;
  let src = img, sw = iw, sh = ih;
  if (k < 0.5) {
    const mid = document.createElement('canvas');
    mid.width = Math.max(2, Math.round(iw * 0.5)); mid.height = Math.max(2, Math.round(ih * 0.5));
    const mc = mid.getContext('2d'); mc.imageSmoothingQuality = 'high'; mc.drawImage(img, 0, 0, mid.width, mid.height);
    src = mid; sw = mid.width; sh = mid.height;
  }
  const cv = document.createElement('canvas');
  cv.width = Math.max(2, Math.round(iw * k)); cv.height = Math.max(2, Math.round(ih * k));
  const c = cv.getContext('2d', { willReadFrequently: true });
  c.imageSmoothingQuality = 'high';
  c.drawImage(src, 0, 0, sw, sh, 0, 0, cv.width, cv.height);
  if (f.brightness !== 1 || f.saturate !== 1 || f.contrast !== 1) {
    const d = c.getImageData(0, 0, cv.width, cv.height), p = d.data;
    for (let i = 0; i < p.length; i += 4) {
      let r = p[i] * f.brightness, g = p[i + 1] * f.brightness, b = p[i + 2] * f.brightness;
      const l = 0.2126 * r + 0.7152 * g + 0.0722 * b;
      r = l + (r - l) * f.saturate; g = l + (g - l) * f.saturate; b = l + (b - l) * f.saturate;
      r = (r - 128) * f.contrast + 128; g = (g - 128) * f.contrast + 128; b = (b - 128) * f.contrast + 128;
      p[i] = r; p[i + 1] = g; p[i + 2] = b;
    }
    c.putImageData(d, 0, 0);
  }
  cv.naturalWidth = iw; cv.naturalHeight = ih;
  byImg.set(filter, cv);
  return cv;
}

// Draw image with cover-fit and smooth log-space cinematic camera motion
export function drawPhotoCamera(ctx, img, t, dur, cam = {}) {
  const k = clamp(t / Math.max(0.01, dur));
  const e = cam.ease === 'sine' ? easeInOutSine(k) : k;
  const z0 = cam.z0 ?? 1.04;
  const z1 = cam.z1 ?? 1.12;
  const z = Math.exp(lerp(Math.log(z0), Math.log(z1), e));
  const dx = lerp(cam.x0 ?? 0, cam.x1 ?? 0, e);
  const dy = lerp(cam.y0 ?? 0, cam.y1 ?? 0, e);

  const filtered = bakedImage(img, cam.filter);
  const imgRatio = (img.naturalWidth || img.width) / (img.naturalHeight || img.height);
  const cvRatio = W / H;
  let dw, dh;
  if (imgRatio > cvRatio) {
    dh = H;
    dw = dh * imgRatio;
  } else {
    dw = W;
    dh = dw / imgRatio;
  }

  ctx.save();
  ctx.translate(W / 2 + dx, H / 2 + dy);
  ctx.scale(z, z);
  ctx.drawImage(filtered, -dw / 2, -dh / 2, dw, dh);
  ctx.restore();
}

// Soft film vignette & subtle top/bottom cinematic gradient
export function drawFilmGrade(ctx, { tint = null, tintAlpha = 0, vignette = 0.42 } = {}) {
  if (tint && tintAlpha > 0) {
    ctx.save();
    ctx.globalAlpha = tintAlpha;
    ctx.fillStyle = tint;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();
  }
  const v = ctx.createRadialGradient(W * 0.5, H * 0.48, H * 0.25, W * 0.5, H * 0.5, W * 0.68);
  v.addColorStop(0, 'rgba(0,0,0,0)');
  v.addColorStop(1, `rgba(4,10,10,${vignette})`);
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, W, H);

  // Subtle bottom gradient for subtitle legibility
  const bg = ctx.createLinearGradient(0, H * 0.72, 0, H);
  bg.addColorStop(0, 'rgba(3,8,8,0)');
  bg.addColorStop(1, 'rgba(3,8,8,0.68)');
  ctx.fillStyle = bg;
  ctx.fillRect(0, H * 0.72, W, H * 0.28);
}

// Soft organic volumetric golden/emerald light beam (no hard polygon edges)
export function drawSunShaft(ctx, t, { x = W * 0.65, y = -80, spread = 420, color = 'rgba(240,210,120,0.22)', pulse = 0.2 } = {}) {
  ctx.save();
  const sway = Math.sin(t * 0.55) * 30;
  const alpha = 0.85 + Math.sin(t * 0.9) * pulse;
  ctx.globalCompositeOperation = 'screen';
  ctx.globalAlpha = clamp(alpha, 0.25, 1.15);
  ctx.translate(x + sway, y + H * 0.42);
  ctx.rotate(0.24);
  ctx.scale(1.0, 2.6);
  const r = spread * 0.85;
  const g = ctx.createRadialGradient(0, 0, r * 0.05, 0, 0, r);
  g.addColorStop(0, color);
  g.addColorStop(0.55, color.replace(/[\d.]+\)$/, '0.07)'));
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, r, 0, TAU);
  ctx.fill();
  ctx.restore();
}

// Ethereal emerald & gold floating particles
export function drawParticles(ctx, t, {
  count = 55,
  mode = 'emerald-gold',
  speed = 1.0,
  alpha = 0.85,
  seed = 1,
} = {}) {
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  for (let i = 0; i < count; i++) {
    const h1 = hash(i * 1.13 + seed * 17);
    const h2 = hash(i * 2.41 + seed * 31);
    const h3 = hash(i * 3.77 + seed * 47);
    const h4 = hash(i * 5.09 + seed * 59);

    const px = ((h1 * W + Math.sin(t * (0.4 + h3 * 0.7) + h4 * TAU) * (36 + h2 * 40) + t * (h4 - 0.5) * 28 * speed) % (W + 120) + (W + 120)) % (W + 120) - 60;
    const py = ((h2 * H - t * (18 + h3 * 36) * speed) % (H + 120) + (H + 120)) % (H + 120) - 60;
    const r = 1.6 + h4 * 4.4;
    const twinkle = 0.45 + 0.55 * Math.sin(t * (1.4 + h3 * 2.2) + h1 * TAU);

    let c1, c2;
    if (mode === 'gold') {
      c1 = 'rgba(255,232,165,0.95)';
      c2 = 'rgba(217,175,82,0)';
    } else if (mode === 'mist') {
      c1 = 'rgba(180,210,215,0.35)';
      c2 = 'rgba(180,210,215,0)';
    } else {
      const isGold = h3 > 0.48;
      c1 = isGold ? 'rgba(248,220,132,0.95)' : 'rgba(116,238,170,0.9)';
      c2 = isGold ? 'rgba(217,175,82,0)' : 'rgba(14,140,95,0)';
    }

    const rad = r * (mode === 'mist' ? 14 : 3.2);
    const g = ctx.createRadialGradient(px, py, 0, px, py, rad);
    g.addColorStop(0, c1);
    g.addColorStop(1, c2);
    ctx.globalAlpha = alpha * twinkle;
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(px, py, rad, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

// Flowing emerald-gold magical aura ribbons (for Gaia scenes E02-G03)
export function drawAuraRibbons(ctx, t, { intensity = 0.55, yCenter = H * 0.58, count = 3 } = {}) {
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  for (let r = 0; r < count; r++) {
    ctx.beginPath();
    const phase = t * (0.7 + r * 0.25) + r * 2.1;
    const amp = 55 + r * 28;
    for (let x = -40; x <= W + 40; x += 28) {
      const nx = x / W;
      const y = yCenter + Math.sin(nx * 5.2 + phase) * amp + Math.cos(nx * 2.8 - phase * 0.7) * (amp * 0.45);
      if (x === -40) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    const g = ctx.createLinearGradient(0, yCenter - amp, W, yCenter + amp);
    g.addColorStop(0, 'rgba(85,220,150,0)');
    g.addColorStop(0.3, `rgba(110,235,165,${0.32 * intensity})`);
    g.addColorStop(0.55, `rgba(246,216,120,${0.42 * intensity})`);
    g.addColorStop(0.8, `rgba(95,210,140,${0.25 * intensity})`);
    g.addColorStop(1, 'rgba(217,175,82,0)');
    ctx.strokeStyle = g;
    ctx.lineWidth = 10 + r * 7;
    ctx.lineCap = 'round';
    ctx.shadowColor = 'rgba(130,245,175,0.6)';
    ctx.shadowBlur = 24;
    ctx.stroke();
  }
  ctx.restore();
}

// Procedural lush Indonesian tropical forest & misty mountain range at dawn (for A02)
export function drawDawnForestA02(ctx, t, dur) {
  const k = clamp(t / dur);
  // Dawn sky gradient
  const sky = ctx.createLinearGradient(0, 0, 0, H);
  sky.addColorStop(0, '#133245');
  sky.addColorStop(0.35, '#2b616e');
  sky.addColorStop(0.68, '#d4a36a');
  sky.addColorStop(1, '#f3d49c');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, H);

  // Soft rising dawn sun glow
  const sunX = W * lerp(0.58, 0.54, k);
  const sunY = H * lerp(0.46, 0.41, k);
  const sun = ctx.createRadialGradient(sunX, sunY, 10, sunX, sunY, 540);
  sun.addColorStop(0, 'rgba(255,246,214,0.95)');
  sun.addColorStop(0.25, 'rgba(248,205,126,0.55)');
  sun.addColorStop(1, 'rgba(248,205,126,0)');
  ctx.fillStyle = sun;
  ctx.fillRect(0, 0, W, H);

  // Parallax mountain & rainforest ridges (5 depth layers)
  const layers = [
    { yBase: 460, amp: 120, freq: 0.0022, speed: 18, color: '#274d56', mist: 0.42 },
    { yBase: 550, amp: 95,  freq: 0.0031, speed: 34, color: '#1e4b45', mist: 0.34 },
    { yBase: 645, amp: 78,  freq: 0.0044, speed: 56, color: '#154337', mist: 0.28 },
    { yBase: 745, amp: 60,  freq: 0.0062, speed: 88, color: '#0e3628', mist: 0.22 },
    { yBase: 860, amp: 48,  freq: 0.0095, speed: 130, color: '#082319', mist: 0.14 },
  ];

  layers.forEach((L, idx) => {
    const shift = t * L.speed;
    ctx.beginPath();
    ctx.moveTo(0, H);
    for (let x = 0; x <= W + 20; x += 16) {
      const wx = x + shift;
      const ridge =
        Math.sin(wx * L.freq + idx * 1.9) * L.amp * 0.65 +
        Math.sin(wx * L.freq * 2.3 + idx * 4.1) * L.amp * 0.3 +
        (idx >= 2 ? Math.sin(wx * 0.045 + idx) * 9 : 0); // canopy texture
      ctx.lineTo(x, L.yBase - ridge + k * (idx * 6));
    }
    ctx.lineTo(W, H);
    ctx.closePath();
    ctx.fillStyle = L.color;
    ctx.fill();

    // Valley mist band between ridges
    const mistG = ctx.createLinearGradient(0, L.yBase - 40, 0, L.yBase + 110);
    mistG.addColorStop(0, 'rgba(245,234,205,0)');
    mistG.addColorStop(0.5, `rgba(242,232,208,${L.mist})`);
    mistG.addColorStop(1, 'rgba(242,232,208,0)');
    ctx.fillStyle = mistG;
    ctx.fillRect(0, L.yBase - 40, W, 150);
  });

  // Winding luminous river glint in the valley
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  ctx.beginPath();
  ctx.moveTo(W * 0.52 - t * 6, 610);
  ctx.bezierCurveTo(W * 0.44, 700, W * 0.62, 780, W * 0.46 - t * 14, H);
  ctx.strokeStyle = 'rgba(248,225,172,0.34)';
  ctx.lineWidth = 42;
  ctx.shadowColor = 'rgba(255,230,170,0.45)';
  ctx.shadowBlur = 24;
  ctx.stroke();
  ctx.restore();

  drawSunShaft(ctx, t, { x: sunX + 60, spread: 520, color: 'rgba(255,232,168,0.26)' });
  drawParticles(ctx, t, { count: 40, mode: 'gold', speed: 0.7, alpha: 0.65, seed: 22 });
}

// Unobtrusive "ILUSTRASI" badge for real-world scenes (00:00–01:05 per §7)
export function drawIlustrasiBadge(ctx, t, dur) {
  return; // web: badge removed at the owner's request
  const a = easeOutCubic(span(t, 0.25, 0.85)) * (1 - easeOutCubic(span(t, dur - 0.35, dur)));
  if (a <= 0.01) return;
  ctx.save();
  ctx.globalAlpha = 0.72 * a;
  ctx.fillStyle = 'rgba(8, 16, 18, 0.56)';
  ctx.beginPath();
  ctx.roundRect(54, 46, 146, 36, 18);
  ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,0.22)';
  ctx.lineWidth = 1.2;
  ctx.stroke();
  ctx.fillStyle = '#E8EFEA';
  ctx.font = '600 16px "Segoe UI", system-ui, sans-serif';
  ctx.letterSpacing = '2.4px';
  ctx.textBaseline = 'middle';
  ctx.fillText('ILUSTRASI', 76, 65);
  ctx.restore();
}

// Editorial Fact Card (§7 — clean, readable on desktop & mobile, UNEP/SIPSN attributed)
export function drawFactCard(ctx, t, dur, { number, line1, source, x = 96, y = 116, align = 'left' }) {
  const enter = easeOutExpo(span(t, 0.45, 1.35));
  const exit = 1 - easeInOutSine(span(t, dur - 0.65, dur - 0.1));
  const a = enter * exit;
  if (a <= 0.01) return;

  const cardW = 660;
  const cardH = 196;
  const cx = align === 'right' ? W - cardW - x : x;
  const cy = y + (1 - enter) * 26;

  ctx.save();
  ctx.globalAlpha = a;

  // Glass card backing
  ctx.fillStyle = 'rgba(7, 17, 20, 0.80)';
  ctx.beginPath();
  ctx.roundRect(cx, cy, cardW, cardH, 18);
  ctx.fill();

  // Left accent bar in warm gold
  ctx.fillStyle = '#E2B857';
  ctx.beginPath();
  ctx.roundRect(cx, cy, 8, cardH, [18, 0, 0, 18]);
  ctx.fill();

  // Subtle border
  ctx.strokeStyle = 'rgba(226, 184, 87, 0.36)';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.roundRect(cx, cy, cardW, cardH, 18);
  ctx.stroke();

  // Big statistic number
  ctx.fillStyle = '#F7D67C';
  ctx.font = '800 50px "Segoe UI", system-ui, sans-serif';
  ctx.textBaseline = 'top';
  ctx.fillText(number, cx + 32, cy + 26);

  // Description line
  ctx.fillStyle = '#F2F5F3';
  ctx.font = '500 25px "Segoe UI", system-ui, sans-serif';
  ctx.fillText(line1, cx + 32, cy + 94);

  // Attribution source
  ctx.fillStyle = 'rgba(202, 218, 214, 0.78)';
  ctx.font = '400 18px "Segoe UI", system-ui, sans-serif';
  ctx.fillText(source, cx + 32, cy + 144);

  ctx.restore();
}

// Clean cinematic Indonesian subtitle renderer
export function drawSubtitle(ctx, globalT, subs) {
  if (!subs || !subs.length) return; // web: captions are HTML
  const active = subs.find(s => globalT >= s.start && globalT <= s.end);
  if (!active) return;

  const a = easeOutCubic(span(globalT, active.start, active.start + 0.22))
    * (1 - easeOutCubic(span(globalT, active.end - 0.22, active.end)));
  if (a <= 0.01) return;

  ctx.save();
  ctx.globalAlpha = a;
  const isGaia = active.speaker === 'Gaia';
  ctx.font = `${isGaia ? 'italic 500' : '500'} 34px Georgia, "Times New Roman", serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  // Word-wrap into max 2 lines (~1340px width)
  const words = active.text.split(' ');
  const lines = [];
  let cur = '';
  for (const w of words) {
    const test = cur ? cur + ' ' + w : w;
    if (ctx.measureText(test).width > 1340 && cur) {
      lines.push(cur);
      cur = w;
    } else {
      cur = test;
    }
  }
  if (cur) lines.push(cur);

  const lineH = 46;
  const baseY = H - 78 - (lines.length - 1) * (lineH / 2);

  // Soft pill backdrop
  const maxW = Math.max(...lines.map(l => ctx.measureText(l).width));
  ctx.fillStyle = 'rgba(4, 12, 12, 0.62)';
  ctx.beginPath();
  ctx.roundRect(W / 2 - maxW / 2 - 34, baseY - 30, maxW + 68, lines.length * lineH + 18, 14);
  ctx.fill();

  // Speaker subtle gold glow for Gaia
  ctx.shadowColor = isGaia ? 'rgba(217, 175, 82, 0.45)' : 'rgba(0, 0, 0, 0.9)';
  ctx.shadowBlur = 12;
  ctx.fillStyle = isGaia ? '#FDF5DF' : '#F4F7F6';
  lines.forEach((line, idx) => {
    ctx.fillText(line, W / 2, baseY + idx * lineH);
  });
  ctx.restore();
}
